"""Build a documentation-only survey guide from the real 64x64 panel renderer.
Run with uv run --no-project build-guide.py --repo /path/to/flockinator.
Requires a C++17 compiler and ffmpeg. Does not connect to hardware or services.
"""
from pathlib import Path
import argparse, subprocess, tempfile, json, hashlib, base64, html, textwrap
p=argparse.ArgumentParser();p.add_argument('--repo',type=Path,required=True);a=p.parse_args()
root=a.repo.resolve();out=Path(__file__).resolve().parent;assets=out/'assets';assets.mkdir(exist_ok=True)
states=json.loads((out/'states.json').read_text());byid={s['id']:s for s in states}
source_paths=['firmware/node-platform/include/recon_render.h','firmware/node-platform/include/pixel_ui.h','firmware/shared/recon/model.h','firmware/shared/recon/font.h','previews/recon-hud/communication.mjs','previews/recon-hud/coordination.mjs','tools/mission-host/coordination_lab.py']
hashes={name:hashlib.sha256((root/name).read_bytes()).hexdigest() for name in source_paths}
with tempfile.TemporaryDirectory(prefix='flockinator-guide-') as tmp:
 temp=Path(tmp);binary=temp/'render';raw=temp/'panels'
 subprocess.run(['clang++','-std=c++17','-O2','-I',str(root/'firmware/node-platform/include'),str(out/'render-panels.cpp'),'-o',str(binary)],check=True)
 subprocess.run([str(binary),str(raw)],check=True)
 for image in sorted(raw.glob('*.ppm')):
  subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-i',str(image),'-vf','scale=256:256:flags=neighbor','-frames:v','1',str(assets/(image.stem+'.png'))],check=True)
 # Validate the actual RGB565-rendered corner pixel at both pulses and both gaps.
 for direction,color in [('TX',bytes([255,137,32])),('RX',bytes([49,238,115]))]:
  for i in range(4):
   content=(raw/f'{direction}-{i}.ppm').read_bytes().split(b'\n',3)[3]
   assert (content[:3]==color)==(i in (0,2)),(direction,i,content[:3],color)
 for src in source_paths:assert hashlib.sha256((root/src).read_bytes()).hexdigest()==hashes[src],f'Source changed while rendering: {src}'

def E(s):return html.escape(str(s),quote=True)
def image_uri(name):return 'data:image/png;base64,'+base64.b64encode((assets/f'{name}.png').read_bytes()).decode()
def svg_start(w,h,title,description):
 return [f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}" role="img" aria-labelledby="title desc"><title id="title">{E(title)}</title><desc id="desc">{E(description)}</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10Z" fill="#7c9f8b"/></marker></defs><rect width="100%" height="100%" rx="20" fill="#0b1916"/><g font-family="Arial, sans-serif" fill="#eff5e8">']
def text(parts,x,y,value,size=16,fill='#eff5e8',weight='normal'):
 parts.append(f'<text x="{x}" y="{y}" font-size="{size}" font-weight="{weight}" fill="{fill}">{E(value)}</text>')
def wrap(parts,x,y,value,width=35,size=15,fill='#b7c9bc'):
 for i,line in enumerate(textwrap.wrap(value,width)):text(parts,x,y+i*(size+6),line,size,fill)
def tile(parts,x,y,state,title,note,w=258):
 parts.append(f'<rect x="{x}" y="{y}" width="{w}" height="162" rx="12" fill="#132820" stroke="#355242"/>')
 parts.append(f'<image href="{image_uri(state)}" x="{x+14}" y="{y+16}" width="84" height="84" style="image-rendering:pixelated"/>')
 text(parts,x+112,y+39,state,16,'#b5f294','bold');wrap(parts,x+112,y+64,title,17,14,'#eff5e8');wrap(parts,x+14,y+124,note,33,13)
def arrow(parts,x1,y1,x2,y2):parts.append(f'<path d="M{x1} {y1} L{x2} {y2}" fill="none" stroke="#7c9f8b" stroke-width="2" marker-end="url(#arrow)"/>')

parts=svg_start(1200,850,'A survey rehearsal, read through its panels','Three rows show preparation, observation and recovery, with actual firmware-rendered thumbnails. This is an annotated route through selected states, not the executable state machine.')
text(parts,40,48,'FLOCKINATOR / FIELD GUIDE 01',15,'#b5f294','bold');text(parts,40,91,'A survey rehearsal, read through its panels',32,weight='bold')
text(parts,40,123,'Selected milestones • code-rendered panels • illustrative route, not an autonomous flight policy',16,'#b7c9bc')
rows=[('01  PREPARE',[("READY","Await a mission","No active task."),("ORDERS","Read the objective","Survey, share data, keep clear."),("TAKEOFF","Enter the simulation","Display transition; no actuators."),("DEPLOY","Form up","Begin the observation role.")]),('02  OBSERVE & COMPARE',[("SCAN","Look for an observation","Search continues without a report."),("SEEN","Notice a candidate","An observation is not a conclusion."),("SHARE","Offer the report","TX names the intended peer."),("CHECK","Seek corroboration","Receipt is not agreement.")]),('03  RECOVER',[("R2B","Return to the base","Mission completion or recovery branch."),("LAND","Finish simulated flight","The home view comes into sight."),("CHARGE","Replenish","Simulated battery animation."),("STANDBY","Wait for the next task","Re-entry requires a new rehearsal.")])]
for r,(title,items) in enumerate(rows):
 y=180+r*211;text(parts,40,y,title,15,'#b5f294','bold')
 for i,(state,title,note) in enumerate(items):
  x=40+i*287;tile(parts,x,y+16,state,title,note)
  if i<3:arrow(parts,x+264,y+96,x+279,y+96)
text(parts,40,826,'A return may branch from observation. Uncertainty can loop through CHECK, DOUBT and SCAN.',15,'#b7c9bc')
parts.append('</g></svg>');(assets/'survey-timeline.svg').write_text(''.join(parts))

parts=svg_start(1200,1130,'Conceptual survey decision tree','This explanatory tree relates mission objectives and observations to display states. Dashed relationships are an interpretive guide, not implemented autonomous transition rules.')
text(parts,40,45,'FLOCKINATOR / FIELD GUIDE 02',15,'#b5f294','bold');text(parts,40,88,'What would justify the next action?',32,weight='bold');text(parts,40,120,'Conceptual survey logic • explanatory captions • no confidence or battery thresholds implied',16,'#b7c9bc')
def box(x,y,w,h,title,body,state=None):
 parts.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="#132820" stroke="#355242"/>')
 off=16
 if state:
  parts.append(f'<image href="{image_uri(state)}" x="{x+14}" y="{y+16}" width="70" height="70" style="image-rendering:pixelated"/>');off=99
 text(parts,x+off,y+34,title,18,'#eff5e8','bold');wrap(parts,x+off,y+59,body,int((w-off-15)/7.5),14)
box(390,160,420,110,'Mission active?','READY → ORDERS. The objective supplies the context.','ORDERS')
arrow(parts,600,270,600,313);text(parts,618,300,'yes',13,'#b7c9bc')
box(390,315,420,110,'Continue this survey?','Consider task completion and the represented recovery state.','HOLD')
arrow(parts,810,370,870,370);text(parts,829,356,'no',13,'#b7c9bc');box(875,315,280,140,'Recover','R2B → LAND → CHARGE / STANDBY.','R2B')
arrow(parts,600,425,600,468);text(parts,618,452,'yes',13,'#b7c9bc')
box(390,470,420,110,'Observation available?','SCAN / LOITER. Keep looking when there is no report.','SCAN')
arrow(parts,390,524,326,524);text(parts,345,510,'no',13,'#b7c9bc');box(40,470,280,110,'Keep observing','No observation is a valid result.','LOITER')
arrow(parts,600,580,600,623);text(parts,618,606,'yes',13,'#b7c9bc')
box(390,625,420,110,'Share and compare','SEEN → SHARE → CHECK. Preserve the report’s source.','SHARE')
arrow(parts,600,735,600,778)
box(390,780,420,110,'Enough independent evidence?','Compare with a peer observation; receipt alone is insufficient.','CHECK')
arrow(parts,390,835,326,835);text(parts,340,820,'unclear',13,'#b7c9bc');box(40,780,280,140,'Keep uncertainty','DOUBT / CHECK / SCAN. Do not invent certainty.','DOUBT')
arrow(parts,600,890,600,933)
box(390,935,420,110,'Record and continue','Retain the supported observation; revisit the mission objective.','SEEN')
text(parts,40,1093,'The current scripted renderer does not evaluate this tree. A causal claim requires an instrumented run.',16,'#b7c9bc')
parts.append('</g></svg>');(assets/'survey-decision-tree.svg').write_text(''.join(parts))

parts=svg_start(1200,620,'The communication double flash','Sender A1 has an orange border and TX B1. Receiver B1 has a green border and RX A1. Both flash on, off, on, then off over 625 milliseconds.')
text(parts,40,48,'FLOCKINATOR / FIELD GUIDE 03',15,'#b5f294','bold');text(parts,40,92,'One illustrated event. Two visible endpoints.',32,weight='bold')
text(parts,40,125,'Orange = TX / sending       Green = RX / receiving       These examples are scripted events.',16,'#b7c9bc')
for i,(timing,sample) in enumerate([('0–250 ms',125),('250–375 ms',312.5),('375–625 ms',500),('625 ms onward',750)]):
 x=220+i*235;text(parts,x,178,timing,17,weight='bold');text(parts,x,202,f'Sample: {sample:g} ms',13,'#b7c9bc')
 for row,direction in enumerate(['TX','RX']):parts.append(f'<image href="{image_uri(direction+"-"+str(i))}" x="{x}" y="{222+row*160}" width="132" height="132" style="image-rendering:pixelated"/>')
text(parts,40,270,'A1 → B1',23,'#ffb16b','bold');text(parts,40,298,'Sender / orange',15,'#b7c9bc');text(parts,40,430,'B1 ← A1',23,'#69ed9a','bold');text(parts,40,458,'Receiver / green',15,'#b7c9bc')
text(parts,40,570,'The TX/RX footer remains during the 125 ms dark gap. After 625 ms, the state’s normal footer returns.',15,'#b7c9bc');text(parts,40,596,'A green flash is not an acknowledgement, a trust score, or evidence that the receiver changed its decision.',15,'#b7c9bc')
parts.append('</g></svg>');(assets/'communication-strip.svg').write_text(''.join(parts))

cards=''.join(f'''<article class="state" data-group="{E(s['group'])}" id="state-{s['id']}"><div class="state-top"><img src="assets/{s['id']}.png" width="128" height="128" loading="lazy" alt="Firmware-rendered {s['id']} panel fixture"><div><span class="eyebrow">{E(s['group'])}</span><h3>{s['id']}</h3><p>{E(s['title'])}</p></div></div><blockquote>“{E(s['caption'])}”</blockquote><details><summary>Meaning and next decision</summary><p>{E(s['meaning'])}</p><p><strong>Next:</strong> {E(s['next'])}</p></details></article>''' for s in states)
filters=''.join(f'<button type="button" data-filter="{E(g)}" aria-pressed="{str(g=="All").lower()}">{E(g)}</button>' for g in ['All','Prepare','Observe','Communicate','Coordinate','Recover','Exceptions'])
html_page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flockinator — Reading the swarm</title><meta name="description" content="A source-backed visual guide to Flockinator’s survey panels, communication flashes and cooperative observation states."><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#main">Skip to guide</a><header><a class="wordmark" href="#">FLOCKINATOR<span>FIELD NOTES / 01</span></a><nav aria-label="Guide sections"><a href="#timeline">Timeline</a><a href="#decisions">Decisions</a><a href="#messages">Messages</a><a href="#atlas">State atlas</a><a href="#evidence">Evidence</a></nav></header><main id="main"><section class="hero"><div><p class="eyebrow">A visual guide to the quadcopter survey rehearsal</p><h1>Reading<br> the swarm.</h1><p class="intro">An observation becomes a report. A report invites another viewpoint. The panels make that sequence visible—provided we know what each signal actually means.</p><div class="actions"><a class="button" href="#timeline">Follow a survey</a><a href="https://github.com/guruswami-ai/flockinator-public/blob/main/docs/scenarios/quadcopter-survey/README.md">Read the full documentation ↗</a></div></div><div class="hero-panels" aria-label="Four firmware-rendered example panels"><figure><img src="assets/SCAN.png" alt="SCAN panel" width="256" height="256"><figcaption>01 / Look</figcaption></figure><figure><img src="assets/SEEN.png" alt="SEEN panel" width="256" height="256"><figcaption>02 / Notice</figcaption></figure><figure><img src="assets/TX-0.png" alt="SHARE panel with orange transmit border" width="256" height="256"><figcaption>03 / Share</figcaption></figure><figure><img src="assets/RX-0.png" alt="CHECK panel with green receive border" width="256" height="256"><figcaption>04 / Compare</figcaption></figure></div></section><aside class="scope"><strong>Know what you are looking at.</strong> These are code-rendered illustrations of the non-weaponized survey scenario. The current panel sequence is scripted. “Thinking” captions explain the intended meaning; they are not captured reasoning or evidence of autonomous flight.</aside>
<section id="timeline"><p class="eyebrow">01 / The mission story</p><h2>Prepare. Observe. Recover.</h2><p class="lead">The objective changes the interpretation of a state: <strong>Observe</strong> surveys the scene; <strong>Compare reports</strong> highlights checking and disagreement; <strong>Recovery</strong> foregrounds returning and availability. These are the model’s existing goal labels.</p><figure class="diagram"><a href="assets/survey-timeline.svg"><img src="assets/survey-timeline.svg" alt="Survey timeline: READY, ORDERS, TAKEOFF, DEPLOY; SCAN, SEEN, SHARE, CHECK; R2B, LAND, CHARGE, STANDBY" width="1200" height="850"></a><figcaption>Selected milestones, not a promise that every node visits every state in this order. Open the diagram for full size.</figcaption></figure><div class="columns"><div><h3>The simulated world</h3><p>The camera view, sensor styling, altitude and battery graphics communicate a simulated situation. A moving view is not proof of a real flight controller, a sensor reading or an optimised route.</p></div><div><h3>The physical panel</h3><p>The ESP32 renders a 64 × 64 frame. Each thumbnail here comes from that firmware renderer with an explicit documentation fixture. It is not a live screenshot.</p></div><div><h3>The experiment</h3><p>The communication-learning lab is a separate controlled exercise. Its observations, decisions and outcomes can test whether messages help. The animation alone cannot.</p></div></div></section>
<section id="decisions"><p class="eyebrow">02 / An explanatory decision tree</p><h2>What would justify the next action?</h2><p class="lead">Use this tree to narrate the survey. It describes questions an experiment should make observable, rather than claiming these are implemented autonomous transition rules.</p><figure class="diagram"><a href="assets/survey-decision-tree.svg"><img src="assets/survey-decision-tree.svg" alt="Conceptual survey tree: consider the objective and recovery, observe, share, compare independent evidence, retain uncertainty where needed, then record and continue" width="1200" height="1130" loading="lazy"></a><figcaption>For actual behaviour, inspect the versioned scenario and its event trace. No real-aircraft thresholds are implied.</figcaption></figure></section>
<section id="messages"><p class="eyebrow">03 / A message is an event, not a conclusion</p><h2>Read the border, then the evidence.</h2><div class="legend"><span><i class="tx"></i><strong>Orange / TX</strong> — sending</span><span><i class="rx"></i><strong>Green / RX</strong> — receiving</span></div><p>The one-pixel border is on for 250 ms, off for 125 ms, on for 250 ms, then off. The footer temporarily shows the peer: <code>TX B1</code> on A1 pairs with <code>RX A1</code> on B1. <code>TX ALL</code> denotes a broadcast; receivers still name the source.</p><figure class="diagram"><a href="assets/communication-strip.svg"><img src="assets/communication-strip.svg" alt="Paired sender and receiver panels at 125, 312.5, 500 and 750 milliseconds, showing the double flash and temporary TX/RX labels" width="1200" height="620" loading="lazy"></a><figcaption>The source colours are #ff8a24 and #32ed70, quantised by the panel’s RGB565 format.</figcaption></figure><div class="columns"><div><h3>“Come and look”</h3><p>SHARE / REPORT followed by CHECK / VERIFY is a useful explanatory vocabulary for inviting corroboration. It is not a literal payload decoded from these images. A real assessment needs the sent report, its receipt and the recipient’s later action.</p></div><div><h3>Broadcast</h3><p>The preview can show one source and multiple recipients from one scripted event. This explains the event’s scope. It does not mean the receiver acknowledged it, believed it or agreed with it.</p></div><div><h3>Missing or conflicting reports</h3><p>LOST concerns an observation. NOLINK concerns the represented stale view. DOUBT concerns conflicting claims. Keep these distinctions visible instead of treating every failure as “bad communication.”</p></div></div><aside class="scope"><strong>Current implementation:</strong> paired borders are derived from shared scenario time and node identities. They are simulated communication indicators, not packet-capture telemetry. READY, APPROVED, ORDERS and BLANK return before the general border overlay.</aside></section>
<section id="coordination"><p class="eyebrow">04 / A shared observation needs an owner</p><h2>The coordination rehearsal.</h2><p class="lead">The browser preview includes a separate 12-second illustration. Roles and P1 labels are predetermined. It makes a cooperative observation story legible; it does not demonstrate a learned auction or consensus protocol.</p><div class="table-wrap"><table><thead><tr><th>Preview time</th><th>Display</th><th>Story shown</th><th>Communication cue</th></tr></thead><tbody><tr><td>0–2 s</td><td>ALERT</td><td>A source announces symbolic beacon P1.</td><td>Source broadcasts.</td></tr><tr><td>2–4 s</td><td>PRIORITY</td><td>P1 is shown first in the task order.</td><td>No new event in this phase.</td></tr><tr><td>4–6 s</td><td>CLAIM / CHECK</td><td>Two selected nodes offer to inspect.</td><td>Claims at 4.000 s and 4.875 s, addressed to the source.</td></tr><tr><td>6–10 s</td><td>ASSIGN / YIELD</td><td>One node owns the observation; others yield.</td><td>The source broadcasts the assignment at 6 s.</td></tr><tr><td>10–12 s</td><td>SEEN / SCAN</td><td>The owner observes; other nodes resume scanning.</td><td>No new event in this phase.</td></tr></tbody></table></div><p class="small">These times describe <code>previews/recon-hud/coordination.mjs</code>, not the firmware’s complete mission schedule. In particular, the assignment broadcaster is the source; its identity can differ from the owner shown on the panels.</p></section>
<section id="atlas"><p class="eyebrow">05 / The panel vocabulary</p><h2>Twenty-five of thirty states, explained.</h2><p class="lead">The first-person lines are presenter captions. Open each card for the visual meaning and the next question to ask. Scope: the firmware enum has 30 states; this atlas shows 25. ENGAGE and KILL are outside this non-weaponised survey scenario; FRIEND, TARGET, and BLANK are not shown.</p><div class="filters" role="group" aria-label="Filter panel states">FILTERS</div><p id="state-count" class="small" aria-live="polite">25 of 30 states shown</p><div class="atlas">CARDS</div></section>
<section id="evidence"><p class="eyebrow">06 / From a flashing frame to a defensible finding</p><h2>Show what changed because of the message.</h2><ol class="evidence-steps"><li><strong>Observation.</strong> What did this node know before receiving the message?</li><li><strong>Communication.</strong> Which source sent which content, and when was it actually received?</li><li><strong>Decision.</strong> What action or symbolic choice followed, and what concise reason code was recorded?</li><li><strong>Outcome.</strong> How did the choice compare with the separately held director truth?</li><li><strong>Counterfactual.</strong> With the same seed and observations, did withholding or scrambling the message change the outcome?</li></ol><p>In the separate learning lab, a listener learns sender–symbol associations from training feedback. During held-out evaluation, decoded peer cues contribute to its symbolic sector choice alongside its private clue. This is receiver learning with assigned sender vocabularies—not a claim that the panel renderer learned a language.</p><p>The Meta reviewers should cite those records and distinguish an observation, an interpretation and a proposed improvement. Reviewing logs does not establish a gain until a new, comparable evaluation measures it. These documentation fixtures are not assessment evidence.</p><div class="columns"><div><h3>Keep a decision record</h3><p>Run ID, node identity, firmware/policy version, simulation tick, observation reference, message source and ID, receipt time, selected action, reason code, uncertainty, outcome and missing-data flags.</p></div><div><h3>Keep conclusions bounded</h3><p>Same-time flashes do not establish causation. More messages do not establish more useful information. A stronger reviewer does not establish a smarter node. Copied SD logs do not establish local execution.</p></div></div></section>
<section id="sources"><p class="eyebrow">07 / Reproducible documentation</p><h2>Pixels from the code. Claims with a source.</h2><p>This package contains the renderer driver, state descriptions, generation script and a <a href="source-manifest.json">source-hash manifest</a>. It makes no network or hardware calls. Use <code>uv run --no-project build-guide.py --repo /path/to/flockinator</code> to regenerate it with C++17 and FFmpeg installed.</p><ul><li><code>firmware/node-platform/include/recon_render.h</code> — actual pixels, captions, colours and pulse timing.</li><li><code>firmware/shared/recon/model.h</code> — scripted states, goals and event construction.</li><li><code>previews/recon-hud/communication.mjs</code> — presentation pairing and broadcasts.</li><li><code>previews/recon-hud/coordination.mjs</code> — the 12-second preview fixture.</li><li><code>tools/mission-host/coordination_lab.py</code> — separate message-learning exercise.</li></ul><p class="small">Scope: non-weaponized survey, cooperative observation and recovery. This guide is not a flight-control manual and does not document attack selection or engagement logic.</p></section></main><footer>FLOCKINATOR / An experimental field guide.<span>Rendered fixtures · not live telemetry</span></footer><script>document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const group=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let shown=0;document.querySelectorAll('.state').forEach(card=>{card.hidden=group!=='All'&&card.dataset.group!==group;if(!card.hidden)shown++});document.querySelector('#state-count').textContent=shown+' states shown'}));</script></body></html>'''.replace('FILTERS',filters).replace('CARDS',cards)
(out/'index.html').write_text(html_page)
(out/'source-manifest.json').write_text(json.dumps({'scope':'documentation-only non-weaponized survey fixtures','source_sha256':hashes,'renderer':'C++ firmware recon::render, RGB565 expanded to RGB888','native_pixels':[64,64],'published_pixels':[256,256],'scaling':'nearest neighbour','fixtures':{'default_node':'A1','receiver_node':'B1','owner_node':'C1','default_phase_seconds':2.1,'approved_phase_seconds':0.1,'crash_phase_seconds':1.2,'motion':34,'launch':1,'sensor':'NV','variation':0,'camera':0,'goal':'Observe','cycle':1,'communication_sample_seconds':[0.125,0.3125,0.5,0.75]},'verified':['35 renders completed','TX/RX border pixels match both flashes and both gaps','source hashes unchanged during render']},indent=2)+'\n')
print('Generated 35 PNGs, 3 standalone SVG infographics, HTML guide and provenance manifest.')

# Keep the Markdown atlas derived from the same state descriptions as the HTML.
readme=out/'README.md'
if readme.exists():
 import re
 entries=[]
 for state in states:
  entries.append(f"### {state['id']} — {state['title']}\n\n![{state['id']} firmware-rendered panel](assets/{state['id']}.png)\n\n**Explanatory caption:** “{state['caption']}”\n\n{state['meaning']}\n\n**Next question or action:** {state['next']}\n")
 section='<!-- STATE_ATLAS_START -->\n\n'+'\n'.join(entries)+'\n<!-- STATE_ATLAS_END -->'
 readme.write_text(re.sub(r'<!-- STATE_ATLAS_START -->.*?<!-- STATE_ATLAS_END -->',lambda _:section,readme.read_text(),flags=re.S))
